__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LEGAL",{enumerable:!0,get:function(){return o}});const o={privacy:{title:'Privacy',updated:'Draft, September 2026',sections:[{heading:'Who we are',body:'Groundhop is made by [COMPANY NAME], [ADDRESS]. Contact: [CONTACT EMAIL]. EU representative: [EU REPRESENTATIVE].'},{heading:'What stays on your phone',body:'Your check-ins, tickets, plans, shirts and photos are stored on your phone. We do not receive them. A backup file you make is yours; we never see it.'},{heading:'Location',body:'Your location is used only on your phone: to recognise the ground you are at when you check in, and to sort matches by distance. It is not sent to us or anyone else.'},{heading:'Data we fetch',body:'The app downloads fixtures, results and tables from OpenLigaDB and loads club crest images from the addresses that service provides. Those servers see your IP address, like any website.'},{heading:'Notifications',body:'Match reminders and goal alerts are scheduled by your phone itself. No push service is involved.'},{heading:'Reports',body:'When you correct a match, type one in by hand, or tell us something is wrong, that report is sent to us: the match it is about, what was wrong, your correction, an anonymous device id, the app version and your phone\'s language -- never your name, e-mail or phone number. It is stored in the EU (Frankfurt) and used only to fix our data and improve the app. When you pick a ground for an imported match, or correct a score, a club name or a ground, that fix is also shared the same way (the text, the answer, and the same anonymous device id), so that once three phones agree, or we check it, the app learns it for every other fan too; the device id is never shown to other fans. Turning off anonymous usage stats in Settings stops this sharing.'},{heading:'Age',body:'Groundhop is for people aged 16 and over.'},{heading:'Your rights',body:'Under the GDPR you can ask what data we hold about you and have it deleted. Almost everything is on your device, and deleting the app deletes it; the one exception is a report you sent us (see "Reports" above), which carries no name, e-mail or phone number to ask by.'},{heading:'Changes',body:'When accounts, sync or payments are added, this policy will be updated before they go live, and the app will tell you.'}]},terms:{title:'Terms of use',updated:'Draft, September 2026',sections:[{heading:'Using Groundhop',body:'Groundhop helps you plan, log and remember football matches. Use it for your own, non-commercial purposes. You must be 16 or older.'},{heading:'Fixture data',body:'Kick-off times and venues come from community sources and can be wrong or change at short notice. Always check with the club before you travel. We are not liable for trips planned on data that turned out to be wrong.'},{heading:'Clubs and crests',body:'Club names and crests belong to the clubs. They are shown only to identify teams. Groundhop is not affiliated with or endorsed by any club, league or association.'},{heading:'Your content',body:'Photos and notes you add stay yours. Do not add content you have no right to use.'},{heading:'No tickets',body:'Groundhop does not sell, resell or transfer match tickets. Keepsake tickets are souvenirs, not admission.'},{heading:'Governing law',body:'[GOVERNING LAW AND VENUE, to be set with legal advice.]'}]},credits:{title:'Credits',updated:'September 2026',sections:[{heading:'Grounds',body:'Ground data \xa9 OpenStreetMap contributors, available under the Open Database License (ODbL). openstreetmap.org/copyright'},{heading:'Clubs and venues',body:'Club-to-ground links partly from Wikidata (CC0).'},{heading:'Fixtures, results and tables',body:'OpenLigaDB (openligadb.de), a community project.'},{heading:'Fonts',body:'Archivo, Archivo Black and Archivo Narrow by Omnibus-Type, under the SIL Open Font License.'},{heading:'Flags',body:'Country flags from flag-icons by Panayiotis Lipiridis, under the MIT License. github.com/lipis/flag-icons'}]}}},1019,[]);